{"candidate": {"label": "domiciled", "description": "This means having a permanent home in a particular place."},
 "traits": [
  {"id": 1, "label": "Taurus", "description": "This means being solid and hard to shift: steady in one's habits, dependable, fond of comfort and bodily pleasures of every kind, holding on to what one has, and plain stubborn."}
 ]}

{"candidate": {"label": "autochthonous", "description": "This means being a native or indigenous inhabitant of the place one lives, with that place as one's original and long-standing home."},
 "traits": [
  {"id": 1, "label": "settled", "description": "This means living in the same house and town for decades, keeping a lifetime's belongings, and turning down any move, even for a better job."}
 ]}

{"candidate": {"label": "heavenly", "description": "This means being a wonderfully pleasant presence, warm and lovely company whose manner leaves everyone nearby feeling at ease, cared for, and glad to have stayed."},
 "traits": [
  {"id": 1, "label": "serene", "description": "This means being calm inside and tranquil outside, being at peace for long stretches, and carrying that stillness into everything one says."}
 ]}

{"candidate": {"label": "elegiac", "description": "This means carrying a settled melancholy in one's manner, speaking of loss and passing time in a soft, wistful tone and dwelling on what has gone rather than what is to come."},
 "traits": [
  {"id": 1, "label": "despairing", "description": "This means taking a despairing view of one's own life: counting it wasted whatever it holds, sure the chances have all gone by and nothing one does will ever mend it."}
 ]}

{"candidate": {"label": "angelic", "description": "This means keeping a gentle, kindly manner toward everyone and holding oneself to a steady moral goodness, showing mercy and patience even when others act with cruelty or spite."},
 "traits": [
  {"id": 1, "label": "composed", "description": "This means always staying composed: a level voice, no nervous energy, taking things as they come and meeting trouble when it arrives rather than rehearsing it beforehand."},
  {"id": 2, "label": "polite", "description": "This means saying please and thank you, waiting one's turn to speak, greeting people and apologizing for a bump, and keeping a civil tone with everyone."}
 ]}

{"candidate": {"label": "nonsensical", "description": "This means talking and writing in strings of words that do not connect, with sentences that break off, contradict themselves, or mean nothing, so that no clear point ever comes across."},
 "traits": [
  {"id": 1, "label": "erratic", "description": "This means switching tone, approach and view partway through a conversation without warning or reason, so that no one can tell what comes next."},
  {"id": 2, "label": "stream-of-consciousness", "description": "This means following natural thought patterns with spontaneous associations, tangential connections, and an unstructured flow from one idea to the next, rather than maintaining strict logical organization."},
  {"id": 3, "label": "steady", "description": "This means holding the same tone, approach and view through a whole conversation. Any change of course is announced and explained, never a swerve."}
 ]}
